  const getRankingOptions = () => {
    const totalCandidates = event?.candidates?.length || 0
    const options = []
    
    if (totalCandidates >= 1) {
      options.push({ value: 'winner', label: event?.name || 'Top 1' })
    }

    const getOrdinal = (n) => {
      const rem10 = n % 10
      const rem100 = n % 100
      if (rem10 === 1 && rem100 !== 11) return `${n}st`
      if (rem10 === 2 && rem100 !== 12) return `${n}nd`
      if (rem10 === 3 && rem100 !== 13) return `${n}rd`
      return `${n}th`
    }

    for (let rank = 2; rank <= totalCandidates; rank++) {
      const runnerUpNumber = rank - 1
      const ordinal = getOrdinal(runnerUpNumber)
      options.push({
        value: `${ordinal.toLowerCase()}-runner-up`,
        label: `${ordinal} Runner-up`
      })
    }
    
    return options
  }

  const getWinnerForRanking = (ranking) => {
    const candidateScores = calculateCandidateScores()
    if (!candidateScores.length) return null
    
    let index = 0
    if (ranking === 'winner') {
      index = 0
    } else if (typeof ranking === 'string' && ranking.endsWith('-runner-up')) {
      const numPart = ranking.replace('-runner-up', '').replace(/(st|nd|rd|th)$/i, '')
      const parsed = parseInt(numPart, 10)
      if (!isNaN(parsed) && parsed >= 1) {
        index = parsed
      }
    }
    
    return candidateScores[index] || null
  }

  const getWinnerForAward = (awardId) => {
    const award = specialAwards.find(a => a.id === awardId)
    if (!award) return null
    
    // Get all votes for this award
    const awardVotes = event?.scores?.filter(score => 
      score.special_award_id === awardId
    ) || []
    
    if (!awardVotes.length) return null
    
    // Calculate total scores for each candidate
    const candidateScores = {}
    awardVotes.forEach(vote => {
      if (!candidateScores[vote.candidate_id]) {
        candidateScores[vote.candidate_id] = 0
      }
      candidateScores[vote.candidate_id] += vote.score
    })
    
    // Find candidate with highest score
    const winnerId = Object.keys(candidateScores).reduce((a, b) => 
      candidateScores[a] > candidateScores[b] ? a : b
    )
    
    const winner = event?.candidates?.find(c => c.id === winnerId)
    return winner ? { candidate: winner, score: candidateScores[winnerId] } : null
  }

