  const handleRestoreEvent = async () => {
    if (!restoreFile) {
      toast.error('Please select a backup file')
      return
    }

    try {
      setIsRestoring(true)
      
      // Read the file
      const fileContent = await restoreFile.text()
      const backupData = JSON.parse(fileContent)

      // Validate backup data
      if (!backupData.version || backupData.type !== 'scores_only') {
        throw new Error('Invalid backup file format. Please use a scores-only backup file.')
      }

      // Confirm restoration
      if (!window.confirm(
        `This will restore scores from "${backupData.eventInfo.name}":\n\n` +
        `- ${backupData.scores?.length || 0} criteria scores\n` +
        `- ${backupData.specialAwardVotes?.length || 0} special award votes\n\n` +
        `Current scores will be REPLACED.\n` +
        `Criteria, candidates, and judges will remain unchanged.\n\n` +
        `Continue?`
      )) {
        setIsRestoring(false)
        return
      }

      // Delete existing scores only (not criteria, candidates, or judges)
      await Promise.all([
        supabase.from(TABLES.SCORES).delete().eq('event_id', eventId),
        supabase.from(TABLES.SPECIAL_AWARD_VOTES).delete().eq('event_id', eventId)
      ])

      let restoredCount = 0
      let skippedCount = 0

      // Restore criteria scores by matching judge_number, candidate_number, and criteria_name
      if (backupData.scores?.length > 0) {
        for (const scoreData of backupData.scores) {
          // Find matching judge by judge_number
          const judge = event.judges?.find(j => j.judge_number === scoreData.judge_number)
          
          // Find matching candidate by candidate_number
          const candidate = event.candidates?.find(c => c.candidate_number === scoreData.candidate_number)
          
          // Find matching criteria by name
          const criteria = event.criteria?.find(cr => cr.name === scoreData.criteria_name)

          if (judge && candidate && criteria) {
            const { error } = await supabase
              .from(TABLES.SCORES)
              .insert({
                event_id: eventId,
                judge_id: judge.id,
                candidate_id: candidate.id,
                criteria_id: criteria.id,
                score: scoreData.score
              })

            if (error) {
              console.warn('Failed to restore score:', scoreData, error)
              skippedCount++
            } else {
              restoredCount++
            }
          } else {
            console.warn('Could not match score data:', {
              scoreData,
              foundJudge: !!judge,
              foundCandidate: !!candidate,
              foundCriteria: !!criteria
            })
            skippedCount++
          }
        }
      }

      // Restore special award votes by matching judge_number, candidate_number, and award_name
      if (backupData.specialAwardVotes?.length > 0) {
        for (const voteData of backupData.specialAwardVotes) {
          const judge = event.judges?.find(j => j.judge_number === voteData.judge_number)
          const candidate = event.candidates?.find(c => c.candidate_number === voteData.candidate_number)
          const award = specialAwards?.find(a => a.name === voteData.award_name)

          if (judge && candidate && award) {
            const { error } = await supabase
              .from(TABLES.SPECIAL_AWARD_VOTES)
              .insert({
                event_id: eventId,
                judge_id: judge.id,
                candidate_id: candidate.id,
                special_award_id: award.id,
                score: voteData.score || 1
              })

            if (error) {
              console.warn('Failed to restore vote:', voteData, error)
              skippedCount++
            } else {
              restoredCount++
            }
          } else {
            console.warn('Could not match vote data:', {
              voteData,
              foundJudge: !!judge,
              foundCandidate: !!candidate,
              foundAward: !!award
            })
            skippedCount++
          }
        }
      }

      const message = skippedCount > 0 
        ? `Scores restored: ${restoredCount} successful, ${skippedCount} skipped (no match found)`
        : `All ${restoredCount} scores restored successfully!`

      toast.success(message)
      setShowRestoreModal(false)
      setRestoreFile(null)
      await fetchEventData()
      
    } catch (error) {
      console.error('Error restoring scores:', error)
      toast.error(`Failed to restore scores: ${error.message}`)
    } finally {
      setIsRestoring(false)
    }
  }

