  const handleCastBackgroundUpload = (e) => {
    const file = e.target.files[0]
    if (file) {
      // Check if it's an image or video
      const validTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'video/mp4', 'video/webm', 'video/ogg']
      if (!validTypes.includes(file.type)) {
        toast.error('Please upload an image (JPEG, PNG, GIF, WEBP) or video (MP4, WEBM, OGG)')
        return
      }

      // Check file size (max 50MB)
      if (file.size > 50 * 1024 * 1024) {
        toast.error('File size must be less than 50MB')
        return
      }

      const reader = new FileReader()
      reader.onloadend = () => {
        setCastBackgroundFile(file)
        setCastBackgroundPreview(reader.result)
      }
      reader.readAsDataURL(file)
    }
  }

  const handleSaveCastBackground = async () => {
    if (!castBackgroundFile) {
      toast.error('Please select a file first')
      return
    }

    setUploadingBackground(true)
    try {
      // Delete old file if exists
      if (event.cast_background_url) {
        try {
          const oldUrl = event.cast_background_url
          const oldFileName = oldUrl.split('/').pop().split('?')[0] // Get filename without query params
          await supabase.storage
            .from('event-logos')
            .remove([oldFileName])
        } catch (err) {
          console.log('Could not delete old file:', err)
          // Continue even if deletion fails
        }
      }

      // Upload file to Supabase Storage
      const fileExt = castBackgroundFile.name.split('.').pop()
      const fileName = `cast-bg-${eventId}-${Date.now()}.${fileExt}`

      const { error: uploadError } = await supabase.storage
        .from('event-logos')
        .upload(fileName, castBackgroundFile, {
          cacheControl: '3600',
          upsert: true
        })

      if (uploadError) throw uploadError

      // Get public URL with cache busting
      const { data: { publicUrl } } = supabase.storage
        .from('event-logos')
        .getPublicUrl(fileName)

      // Add cache-busting parameter
      const urlWithCacheBust = `${publicUrl}?t=${Date.now()}`

      // Update event with cast background URL
      const { error: updateError } = await supabase
        .from(TABLES.EVENTS)
        .update({
          cast_background_url: urlWithCacheBust,
          cast_background_type: castBackgroundFile.type.startsWith('video') ? 'video' : 'image'
        })
        .eq('id', eventId)

      if (updateError) throw updateError

      toast.success('Cast background saved successfully')
      setCastBackgroundFile(null)
      setCastBackgroundPreview(null)
      setShowEventSettingsModal(false)
      
      // Log activity
      await logActivity('update', 'cast_background', null, 'Cast Background', {
        description: `Uploaded ${castBackgroundFile.type.startsWith('video') ? 'video' : 'image'} background`,
        file_type: castBackgroundFile.type
      })
      
      // Force a complete refresh by reloading event data
      await fetchEventData()
      
      // Force re-render by updating a timestamp
      setEvent(prev => ({...prev, _updated: Date.now()}))
    } catch (error) {
      console.error('Error saving cast background:', error)
      toast.error('Failed to save cast background')
    } finally {
      setUploadingBackground(false)
    }
  }

