  const handleSaveEdit = async () => {
    if (!validateEditData()) return

    // Check if there are existing scores
    const hasScores = event.scores && event.scores.length > 0

    // Identify criteria and candidates to be deleted
    const existingCriteriaIds = editData.criteria.filter(c => c.id).map(c => c.id)
    const allCriteriaIds = event.criteria.map(c => c.id)
    const criteriaToDelete = allCriteriaIds.filter(id => !existingCriteriaIds.includes(id))

    const existingCandidateIds = editData.candidates.filter(c => c.id).map(c => c.id)
    const allCandidateIds = event.candidates.map(c => c.id)
    const candidatesToDelete = allCandidateIds.filter(id => !existingCandidateIds.includes(id))

    // Warn if trying to delete criteria/candidates when scores exist
    if (hasScores && (criteriaToDelete.length > 0 || candidatesToDelete.length > 0)) {
      const deletingCriteria = criteriaToDelete.length > 0
      const deletingCandidates = candidatesToDelete.length > 0
      
      let warningMessage = '⚠️ WARNING: This event has existing scores!\n\n'
      
      if (deletingCriteria) {
        const criteriaNames = event.criteria
          .filter(c => criteriaToDelete.includes(c.id))
          .map(c => `• ${c.name}`)
          .join('\n')
        warningMessage += `Removing criteria will DELETE all scores for:\n${criteriaNames}\n\n`
      }
      
      if (deletingCandidates) {
        const candidateNames = event.candidates
          .filter(c => candidatesToDelete.includes(c.id))
          .map(c => `• ${c.name}`)
          .join('\n')
        warningMessage += `Removing candidates will DELETE all scores for:\n${candidateNames}\n\n`
      }
      
      warningMessage += 'This action CANNOT be undone!\n\nAre you absolutely sure you want to continue?'
      
      if (!window.confirm(warningMessage)) {
        setSaving(false)
        return
      }
    }

    setSaving(true)
    try {
      // Upload new logo if provided
      let logoUrl = editData.logoPreview
      if (editData.logo) {
        const fileExt = editData.logo.name.split('.').pop()
        const fileName = `${Date.now()}.${fileExt}`
        const { error: uploadError } = await supabase.storage
          .from('event-logos')
          .upload(fileName, editData.logo)
        
        if (uploadError) throw uploadError
        
        const { data: { publicUrl } } = supabase.storage
          .from('event-logos')
          .getPublicUrl(fileName)
        logoUrl = publicUrl
      }

      // Update event basic info (safe - doesn't affect scores)
      const { error: eventError } = await supabase
        .from(TABLES.EVENTS)
        .update({
          name: editData.name,
          logo_url: logoUrl
        })
        .eq('id', eventId)

      if (eventError) throw eventError

      // Log event updates
      if (event.name !== editData.name) {
        await logActivity('update', 'event', eventId, event.name, {
          description: `Changed event name from "${event.name}" to "${editData.name}"`,
          old_name: event.name,
          new_name: editData.name
        })
      }
      if (editData.logo) {
        await logActivity('update', 'event', eventId, editData.name, {
          description: 'Updated event logo'
        })
      }

      // Delete removed criteria (will cascade delete related scores - user confirmed above)
      if (criteriaToDelete.length > 0) {
        const deletedCriteria = event.criteria.filter(c => criteriaToDelete.includes(c.id))
        const { error: deleteError } = await supabase
          .from(TABLES.CRITERIA)
          .delete()
          .in('id', criteriaToDelete)
        if (deleteError) throw deleteError
        
        // Log deletions
        for (const criterion of deletedCriteria) {
          await logActivity('delete', 'criteria', criterion.id, criterion.name, {
            description: `Deleted criteria (${criterion.percentage}%)`,
            percentage: criterion.percentage
          })
        }
      }

      // Update or insert criteria
      for (const criterion of editData.criteria) {
        if (criterion.id) {
          // Check if it was actually modified
          const original = event.criteria.find(c => c.id === criterion.id)
          const wasModified = original && (
            original.name !== criterion.name ||
            original.percentage !== criterion.percentage ||
            (original.description || '') !== (criterion.description || '')
          )
          
          // Update existing
          const { error } = await supabase
            .from(TABLES.CRITERIA)
            .update({
              name: criterion.name,
              description: criterion.description || '',
              percentage: criterion.percentage
            })
            .eq('id', criterion.id)
          if (error) throw error
          
          // Log update if changed
          if (wasModified) {
            await logActivity('update', 'criteria', criterion.id, criterion.name, {
              description: `Updated criteria (${criterion.percentage}%)`,
              percentage: criterion.percentage
            })
          }
        } else {
          // Insert new
          const { data, error } = await supabase
            .from(TABLES.CRITERIA)
            .insert({
              event_id: eventId,
              name: criterion.name,
              description: criterion.description || '',
              percentage: criterion.percentage
            })
            .select()
          if (error) throw error
          
          // Log creation
          await logActivity('create', 'criteria', data[0]?.id, criterion.name, {
            description: `Added new criteria (${criterion.percentage}%)`,
            percentage: criterion.percentage
          })
        }
      }

      // Delete removed candidates (will cascade delete related scores - user confirmed above)
      if (candidatesToDelete.length > 0) {
        const deletedCandidates = event.candidates.filter(c => candidatesToDelete.includes(c.id))
        const { error: deleteError } = await supabase
          .from(TABLES.CANDIDATES)
          .delete()
          .in('id', candidatesToDelete)
        if (deleteError) throw deleteError
        
        // Log deletions
        for (const candidate of deletedCandidates) {
          await logActivity('delete', 'candidate', candidate.id, candidate.name, {
            description: `Deleted candidate #${candidate.candidate_number}`,
            candidate_number: candidate.candidate_number,
            representation: candidate.representation
          })
        }
      }

      // Update or insert candidates
      for (const candidate of editData.candidates) {
        if (candidate.id) {
          // Check if it was actually modified
          const original = event.candidates.find(c => c.id === candidate.id)
          const wasModified = original && (
            original.name !== candidate.name ||
            original.representation !== candidate.representation ||
            original.candidate_number !== candidate.candidate_number
          )
          
          // Update existing
          const { error } = await supabase
            .from(TABLES.CANDIDATES)
            .update({
              name: candidate.name,
              representation: candidate.representation,
              candidate_number: candidate.candidate_number
            })
            .eq('id', candidate.id)
          if (error) throw error
          
          // Log update if changed
          if (wasModified) {
            await logActivity('update', 'candidate', candidate.id, candidate.name, {
              description: `Updated candidate #${candidate.candidate_number}`,
              candidate_number: candidate.candidate_number,
              representation: candidate.representation
            })
          }
        } else {
          // Insert new
          const { data, error } = await supabase
            .from(TABLES.CANDIDATES)
            .insert({
              event_id: eventId,
              name: candidate.name,
              representation: candidate.representation,
              candidate_number: candidate.candidate_number
            })
            .select()
          if (error) throw error
          
          // Log creation
          await logActivity('create', 'candidate', data[0]?.id, candidate.name, {
            description: `Added new candidate #${candidate.candidate_number}`,
            candidate_number: candidate.candidate_number,
            representation: candidate.representation
          })
        }
      }

      toast.success('Event updated successfully!')
      await fetchEventData()
      setActiveTab('overview')
    } catch (error) {
      console.error('Error updating event:', error)
      toast.error('Failed to update event. Please try again.')
    } finally {
      setSaving(false)
    }
  }

